 mcq("That argument doesn't ___ water.", ["hold","carry","keep","bear"], "hold water = be logically sound."),
 mcq("We must not ___ the importance of public trust.", ["underestimate", "undermine", "undertake", "understatement"], "underestimate = think something is less important than it is."),
 mcq("Her proposal was met with widespread ___.", ["scepticism","sceptical","sceptic","scepticise"], "A noun is needed after 'widespread'."),
 mcq("The council ___ a compromise after hours of negotiation.", ["hammered out", "hammered in", "knocked about", "pulled through"], "hammer out = reach an agreement after long discussion."),
 mcq("The lord's claims are not ___ by the evidence.", ["substantiated", "substituted", "subsidised", "subordinated"], "substantiate = support with proof."),
 mcq("He tends to ___ around the bush instead of answering directly.", ["beat","hit","shake","run"], "beat around the bush = avoid the main point."),
 mcq("The decision will have far-___ consequences.", ["reaching", "fetched", "extending", "flung"], "far-reaching = wide-ranging. (far-fetched = unlikely)"),
 mcq("Her ___ analysis exposed several flaws in the plan.", ["incisive","indecisive","incessant","inclusive"], "incisive = sharp and clear-thinking."),
 mcq("The debate became increasingly ___, with insults on both sides.", ["acrimonious","harmonious","ceremonious","unanimous"], "acrimonious = angry and bitter."),
 mcq("With ___, it's clear the plan was flawed from the start.", ["hindsight","foresight","insight","oversight"], "hindsight = understanding after the event."),
 mcq("The treaty was a ___ moment in the kingdom's history.", ["pivotal","marginal","trivial","peripheral"], "pivotal = crucially important."),
 mcq("She ___ her opponent's argument point by point.", ["dismantled", "disbanded", "dislodged", "disentangled"], "dismantle an argument = take it apart."),
 mcq("His apology seemed ___ rather than sincere.", ["perfunctory", "profound", "heartfelt", "wholehearted"], "perfunctory = done with minimum effort, as a formality."),
 mcq("Let's not jump to ___.", ["conclusions", "results", "judgements", "consequences"], "jump to conclusions = decide too quickly."),
 mcq("The new policy aims to ___ the gap between rich and poor.", ["bridge", "build", "raise", "broaden"], "bridge the gap = reduce the difference."),
